      {
        functional: true
      }
    ),
    errorsHandler$: createEffect(
      (actions$ = inject(Actions), service = notificationService()) =>
        errorsHandlerEffect(actions$, formActions, service),
      {
        functional: true,
        dispatch: false
      }
    )
  };
