  loadPage(): void;
  loadFirstPage(): void;
  loadNextPage(): void;
  loadPreviousPage(): void;
  patch(props: ActionPayload<ListActions<Data, Error, Summary, Params>['patch']>): void;
  delete(props: ActionPayload<ListActions<Data, Error, Summary, Params>['delete']>): void;
  initialize(): void;
  reinitialize(): void;
  resetRequestState(): void;
}

